/* Our Work taxonomy (same ids as Admin → Our Work, hp/php/satin-new/portfolio.php) */
const SERVICES={'full-wrap':'Full wrap','partial-wrap':'Partial wrap','colour-change':'Colour change','commercial':'Commercial / fleet','lettering':'Lettering & decals','ppf':'Paint protection film','window-tint':'Window tint','wallpaper':'Wallpaper','window-graphics':'Window graphics','print':'Print','apparel':'Apparel','signage':'Signage'};
const FINISHES={gloss:'Gloss',matte:'Matte',satin:'Satin',metallic:'Metallic',chrome:'Chrome','colour-shift':'Colour shift',carbon:'Carbon fibre',printed:'Printed graphics',clear:'Clear / PPF'};
const kindLabel=(p,w,lang)=>p.services?.[0]&&p.custom?label(SERVICES[p.services[0]]||p.services[0],lang):p.category==='commercial'?w.commercial:p.category==='colour'?w.colour:label(SERVICES[p.services?.[0]]||'Other',lang);
const searchText=p=>[p.title,...(p.tags||[]),p.model,p.make,p.year,p.client,p.vehicle,p.industry,p.description,...(p.services||[]).map(s=>SERVICES[s]),...(p.finishes||[]).map(f=>FINISHES[f])].filter(Boolean).join(' ').toLowerCase();
const label=(s,lang)=>lang==='en'?s:vocab[s]?.[['fa','fr','es'].indexOf(lang)]||s;
const base=lang=>'/satin'+(lang==='en'?'':'/'+lang);
const origin='https://satin-graphic-website.mehrad-tr.chatgpt.site';
const image=p=>p.cover||p.images[0];
function card(p,lang){const w=words[lang];return `<a class="portfolio-card" href="${base(lang)}/portfolio/projects/${p.slug}/"><div class="portfolio-card-photo"><img src="${image(p).thumb||image(p).src}" alt="${esc(image(p).alt)}" width="640" height="450" loading="lazy"><span>${p.images.length} ${w.photos}</span></div><div class="portfolio-card-info"><small>${p.featured?'★ ':''}${kindLabel(p,w,lang)}${p.vehicle?' · '+esc(label(p.vehicle,lang)):''}</small><h2>${esc(p.title)}</h2><div class="portfolio-tags">${p.tags.slice(0,3).map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div><span class="portfolio-view">${w.view} ↗</span></div></a>`;}
export function portfolioPage(lang='en',path='/portfolio',query=new URLSearchParams(),records=projects){
const projects=records;lastRecords=records;const w=words[lang]||words.en,slug=path.split('/projects/')[1],p=slug?projects.find(p=>p.slug===slug):null,b=base(lang);if(slug&&!p)return null;
if(p){const category=kindLabel(p,w,lang);const html=`<section class="portfolio-project-hero"><div class="wrap"><nav class="portfolio-crumbs" aria-label="Breadcrumb"><a href="${b}/">Satin Graphic</a><span>/</span><a href="${b}/portfolio/">${w.portfolio}</a><span>/</span><span>${esc(p.title)}</span></nav><div class="portfolio-project-top"><div><span class="eyebrow">${category}</span><h1>${esc(p.title)}</h1><p>${description(p,lang)}</p><div class="portfolio-tags">${p.tags.map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div></div><a class="btn" href="${b}/contact/">${w.quote}</a></div><figure><img src="${image(p).src}" alt="${esc(image(p).alt)}" width="${image(p).width}" height="${image(p).height}" fetchpriority="high"><figcaption>${esc(p.title)} · ${category}</figcaption></figure></div></section><section class="portfolio-project-details"><div class="wrap"><h2>${w.details}</h2><dl>${[[w.vehicle,p.custom?[label(p.vehicle,lang),p.model].filter(Boolean).join(' · '):label(p.vehicle||p.model,lang)],[w.services,(p.services||[]).map(s=>label(SERVICES[s]||s,lang)).join(', ')],[w.finish,(p.finishes||[]).map(f=>label(FINISHES[f]||f,lang)).join(', ')],[w.industry,label(p.industry,lang)],[w.coverage,p.custom?'':label(p.coverage,lang)],[w.client,p.client]].filter(a=>a[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>${w.photos}</dt><dd>${p.images.length}</dd></div></dl><div class="portfolio-project-photos">${p.images.map((im,i)=>`<figure><a href="${im.src}" target="_blank" rel="noopener"><img src="${im.src}" alt="${esc(im.alt)}" width="${im.width}" height="${im.height}" loading="lazy"></a><figcaption>${w.photo} ${i+1} · ${esc(p.title)}</figcaption></figure>`).join('')}</div><a href="${b}/portfolio/" class="btn ghost">${w.back}</a></div></section><section class="portfolio-related"><div class="wrap"><h2>${w.related}</h2><div class="portfolio-grid">${[...projects.filter(x=>x.id!==p.id&&x.category===p.category&&(x.vehicle===p.vehicle||x.model===p.model)),...projects.filter(x=>x.id!==p.id&&(x.services||[]).some(s=>(p.services||[]).includes(s))&&!(x.category===p.category&&(x.vehicle===p.vehicle||x.model===p.model)))].slice(0,3).map(x=>card(x,lang)).join('')}</div></div></section>`;return {title:p.title,html,portfolio:true,meta:{title:p.title+' · '+category+' | Satin Graphic',description:description(p,lang),image:image(p).src},record:p};}
const category=path==='/portfolio/commercial'?'commercial':path==='/portfolio/colour-change'?'colour':'',q=(query.get('q')||'').trim().toLowerCase(),vehicle=query.get('vehicle')||'',industry=query.get('industry')||'',coverage=query.get('coverage')||'',service=query.get('service')||'',finish=query.get('finish')||'';
const matches=projects.filter(p=>(!category||p.category===category)&&(!vehicle||p.vehicle===vehicle)&&(!industry||p.industry===industry)&&(!coverage||p.coverage===coverage)&&(!service||(p.services||[]).includes(service))&&(!finish||(p.finishes||[]).includes(finish))&&(!q||q.split(/\s+/).every(t=>searchText(p).includes(t))));const totalPages=Math.max(1,Math.ceil(matches.length/24)),number=Math.min(totalPages,Math.max(1,parseInt(query.get('page'))||1)),slice=matches.slice((number-1)*24,number*24),title=category==='commercial'?w.commercial:category==='colour'?w.colour:w.portfolio;
const options=(key,title)=>`<label>${title}<select name="${key}"><option value="">${w.any}</option>${[...new Set(projects.map(p=>p[key]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${v===query.get(key)?'selected':''}>${esc(label(v,lang))}</option>`).join('')}</select></label>`;
const inCat=projects.filter(p=>!category||p.category===category),serviceCount=Object.keys(SERVICES).map(k=>[k,inCat.filter(p=>(p.services||[]).includes(k)).length]).filter(a=>a[1]),usedFinishes=Object.keys(FINISHES).filter(k=>projects.some(p=>(p.finishes||[]).includes(k)));
const chipHref=k=>{const qs=new URLSearchParams(query);qs.delete('page');if(k)qs.set('service',k);else qs.delete('service');const t=qs.toString();return b+path+'/'+(t?'?'+t:'');};
const pageHref=n=>{const qs=new URLSearchParams(query);qs.set('page',n);return b+path+'/?'+qs.toString();};
const html=`<section class="portfolio-intro"><div class="wrap"><span class="eyebrow">Satin Auto Wrap × Satin Graphic</span><div class="portfolio-intro-top"><h1>${title}</h1><p>${w.intro}</p></div><nav class="portfolio-categories" aria-label="${w.portfolio}">${[['',w.all],['/commercial',w.commercial],['/colour-change',w.colour]].map(([s,t])=>`<a ${path==='/portfolio'+s?'aria-current="page"':''} href="${b}/portfolio${s}/">${t}<small>${projects.filter(p=>!s||p.category===(s==='/commercial'?'commercial':'colour')).length}</small></a>`).join('')}</nav></div></section><section class="portfolio-results"><div class="wrap"><form class="portfolio-filters" data-portfolio-filter action="${b+path}/" method="get"><label class="portfolio-search">${w.search}<input type="search" name="q" value="${esc(query.get('q')||'')}" placeholder="${w.search}"></label>${options('vehicle',w.vehicle)}${options('industry',w.industry)}${options('coverage',w.coverage)}${usedFinishes.length?`<label>${w.finish}<select name="finish"><option value="">${w.any}</option>${usedFinishes.map(k=>`<option value="${k}" ${k===finish?'selected':''}>${esc(label(FINISHES[k],lang))}</option>`).join('')}</select></label>`:''}${service?`<input type="hidden" name="service" value="${esc(service)}">`:''}<button class="btn sm" type="submit">${w.search}</button><a href="${b+path}/">${w.clear}</a></form>${serviceCount.length>1?`<nav class="portfolio-chips" aria-label="${w.services}"><a href="${chipHref('')}" ${!service?'aria-current="true"':''}>${w.allServices}</a>${serviceCount.map(([k,n])=>`<a href="${chipHref(k)}" ${k===service?'aria-current="true"':''}>${esc(label(SERVICES[k],lang))}<small>${n}</small></a>`).join('')}</nav>`:''}<div class="portfolio-count"><span>${matches.length} ${w.results}</span><span>${number} / ${totalPages}</span></div><div class="portfolio-grid">${slice.map(p=>card(p,lang)).join('')}</div>${!matches.length?`<p class="portfolio-no-results">${w.empty}</p>`:''}<nav class="portfolio-pagination" aria-label="Pagination">${number>1?`<a class="btn ghost" href="${pageHref(number-1)}">${w.prev}</a>`:''}${Array.from({length:totalPages},(_,i)=>i+1).filter(n=>n===1||n===totalPages||Math.abs(n-number)<=2).map(n=>`<a href="${pageHref(n)}" ${n===number?'aria-current="page"':''}>${n}</a>`).join('')}${number<totalPages?`<a class="btn ghost" href="${pageHref(number+1)}">${w.next}</a>`:''}</nav></div></section>`;
return {title,html,portfolio:true,meta:{title:title+' · Vehicle wrap portfolio | Satin Graphic',description:w.intro,image:image(slice[0]||projects[0]).src,noindex:!!(q||vehicle||industry||coverage||service||finish)},listing:slice,page:number};
}
function description(p,lang){if(p.description)return esc(p.description);const specs=[p.vehicle||p.model,p.coverage,p.industry].filter(Boolean).map(s=>label(s,lang)).join(' · ');return ({en:`${p.title} — ${p.category==='commercial'?'commercial vehicle graphics':'colour-change wrap'} by Satin Auto Wrap. ${specs}. Explore the finished project and its photos.`,fa:`${p.title} — ${p.category==='commercial'?'رپ تبلیغاتی خودرو':'رپ تغییر رنگ'} توسط Satin Auto Wrap. ${specs}. تصاویر کامل پروژه را ببینید.`,fr:`${p.title} — ${p.category==='commercial'?'marquage de véhicule commercial':'changement de couleur'} par Satin Auto Wrap. ${specs}. Découvrez les photos du projet terminé.`,es:`${p.title} — ${p.category==='commercial'?'rotulación de vehículo comercial':'cambio de color'} de Satin Auto Wrap. ${specs}. Descubre las fotos del proyecto terminado.`})[lang];}
export function portfolioSEO(lang,path,page,query=new URLSearchParams()){
const canonical=origin+base(lang)+path+'/' +(page.page>1&&!page.meta.noindex?'?page='+page.page:''),im=origin+page.meta.image;const graph=[{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Satin Graphic',item:origin+base(lang)+'/'},{'@type':'ListItem',position:2,name:words[lang].portfolio,item:origin+base(lang)+'/portfolio/'},...(page.record?[{'@type':'ListItem',position:3,name:page.record.title,item:canonical}]:[])]}];if(page.record){const p=page.record;graph.push({'@type':'CreativeWork',name:p.title,description:page.meta.description,url:canonical,creator:{'@type':'Organization',name:'Satin Auto Wrap'},keywords:p.tags.join(', '),image:p.images.map(i=>({'@type':'ImageObject',contentUrl:origin+i.src,caption:i.alt,width:i.width,height:i.height}))});}else graph.push({'@type':'CollectionPage',name:page.title,url:canonical,description:page.meta.description,mainEntity:{'@type':'ItemList',itemListElement:page.listing.map((p,i)=>({'@type':'ListItem',position:(page.page-1)*24+i+1,name:p.title,url:origin+base(lang)+'/portfolio/projects/'+p.slug+'/'}))}});return {...page.meta,canonical,image:im,jsonld:{'@context':'https://schema.org','@graph':graph}};}
let lastRecords=null;
function addToIndex(records){const sec=document.querySelector('[data-cms-section="sprojects"]');if(!sec)return;const known=new Set([...sec.querySelectorAll('a[href]')].map(a=>a.getAttribute('href')));const extra=records.filter(p=>p.custom&&!known.has('/satin/portfolio/projects/'+p.slug+'/'));if(!extra.length)return;const ul=sec.querySelector('.proj-index');if(!ul)return;for(const p of extra){const li=document.createElement('li');const a=document.createElement('a');a.href='/satin/portfolio/projects/'+p.slug+'/';a.textContent=p.title;li.append(a);ul.prepend(li);}}
export function mountPortfolio(root,navigate){try{if(lastRecords)addToIndex(lastRecords);}catch{}const form=root.querySelector('[data-portfolio-filter]');if(form){form.addEventListener('submit',e=>{e.preventDefault();const url=new URL(form.action,location.origin);for(const [k,v]of new FormData(form))if(v)url.searchParams.set(k,v);navigate(url);});form.querySelectorAll('select').forEach(s=>s.addEventListener('change',()=>form.requestSubmit()));}}